{
  "application": "report-generation",
  "case_id": "case-ecommerce-amazon-product-ratings-en",
  "language": "en",
  "report": {
    "type": "analytics-report",
    "audience": "management",
    "tone": "analytical, data-forward, actionable"
  },
  "brief": {
    "title": "Amazon Product Catalog Performance & Customer Sentiment Analysis",
    "one_liner": "A comprehensive analysis of 1,400+ Amazon products examining pricing strategies, discount effectiveness, customer ratings, and category-level performance to identify optimization opportunities.",
    "goal": "Equip product and category managers with data-driven insights on which product categories, price ranges, and discount strategies yield the highest customer satisfaction, enabling informed decisions on assortment curation, pricing adjustments, and promotional planning."
  },
  "required_sections": [
    {
      "section_id": "executive-overview",
      "title": "Executive Overview",
      "objective": "Summarize the dataset scope and present headline metrics including total products analyzed, average rating, median discount percentage, and top-performing categories."
    },
    {
      "section_id": "category-analysis",
      "title": "Category Performance Breakdown",
      "objective": "Analyze product distribution, average ratings, and average discount percentages across top-level and sub-level categories. Identify the best- and worst-performing categories by customer rating and engagement (rating_count)."
    },
    {
      "section_id": "pricing-discount-analysis",
      "title": "Pricing & Discount Strategy Analysis",
      "objective": "Examine the relationship between actual price, discounted price, discount percentage, and customer ratings. Determine whether deeper discounts correlate with higher ratings or higher review volumes."
    },
    {
      "section_id": "customer-engagement",
      "title": "Customer Engagement & Rating Distribution",
      "objective": "Profile the distribution of ratings and rating counts across products. Identify products with exceptionally high engagement and analyze what characteristics they share."
    },
    {
      "section_id": "review-sentiment-snapshot",
      "title": "Review Sentiment Snapshot",
      "objective": "Provide a high-level qualitative overview of review titles and content, highlighting common positive and negative themes mentioned by customers."
    },
    {
      "section_id": "recommendations",
      "title": "Strategic Recommendations",
      "objective": "Synthesize findings into 3-5 actionable recommendations for category management, pricing optimization, and customer experience improvement."
    }
  ],
  "kpis": [
    {
      "name": "Average Product Rating",
      "description": "Mean rating across all products in the dataset (scale of 1-5)."
    },
    {
      "name": "Average Discount Percentage",
      "description": "Mean discount percentage offered across all products, indicating overall promotional intensity."
    },
    {
      "name": "Median Rating Count",
      "description": "Median number of customer ratings per product, reflecting typical customer engagement levels."
    },
    {
      "name": "High-Rating Product Share",
      "description": "Percentage of products with a rating of 4.0 or above, indicating catalog quality."
    },
    {
      "name": "Price-to-Discount Efficiency",
      "description": "Correlation between discount percentage and customer rating, measuring whether discounts translate into higher satisfaction."
    }
  ],
  "analysis_dimensions": [
    "category",
    "discounted_price",
    "actual_price",
    "discount_percentage",
    "rating",
    "rating_count"
  ]
}

